```cpp
#include <iostream>
#include <fstream>
#include <string>
#include <map>
#include <vector>
#include <iomanip>
using namespace std;

int main() {
    ifstream plik("wyniki.txt");
    string imie, druzyna;
    int wynik;
    struct Gracz { string imie; string druzyna; int wynik; };
    vector<Gracz> gracze;
    while (plik >> imie >> druzyna >> wynik) {
        gracze.push_back({imie, druzyna, wynik});
    }
    map<string, pair<int,int>> druzynyDane;
    map<string, pair<int,string>> best;
    int sumaAll = 0;
    for (auto& g : gracze) {
        druzynyDane[g.druzyna].first += g.wynik;
        druzynyDane[g.druzyna].second++;
        sumaAll += g.wynik;
        if (g.wynik > best[g.druzyna].first) {
            best[g.druzyna] = {g.wynik, g.imie};
        }
    }
    cout << fixed << setprecision(2);
    cout << "Srednia per druzyna:" << endl;
    for (auto& d : druzynyDane) {
        double avg = (double)d.second.first / d.second.second;
        cout << "   Druzyna " << d.first << ": " << avg << endl;
    }
    cout << "Najlepszy w kazdej druzynie:" << endl;
    for (auto& b : best) {
        cout << "   Druzyna " << b.first << ": " << b.second.second << " (" << b.second.first << ")" << endl;
    }
    double avgAll = (double)sumaAll / gracze.size();
    int powyzej = 0;
    for (auto& g : gracze) {
        if (g.wynik > avgAll) powyzej++;
    }
    cout << "Srednia ogolna: " << avgAll << endl;
    cout << "Zawodnikow powyzej sredniej: " << powyzej << endl;
    return 0;
}
```

